import sys, json

# The adapter that keeps `builder-librarian` unchanged. Two directions, each
# recognised POSITIVELY -- the librarian's own file records why: read phase B as
# "anything that is not a fresh request" and a store error comes back looking
# like a new question, which is the reply-to-fallback loop that really happened
# here before the fix.
doc = json.load(sys.stdin)
env = doc["envelope"]
hop = (env.get("header") or {}).get("hop") or {}
ctx = (env.get("header") or {}).get("context") or {}
msgs = doc["body"].get("messages") or []


def emit(out):
    sys.stdout.write(json.dumps(out))
    sys.exit(0)


# ---- Direction B: the brief comes back. Recognised on the librarian's own
# terminal marker, and ONLY on it.
if hop.get("route") == "brief" and hop.get("stage") == "briefed":
    call_id = str(ctx.get("lib_call_id") or "")
    rows = ""
    for m in msgs:
        if m.get("type") == "tool_result" and m.get("text"):
            rows = m["text"]
    header = {"route": "lib_out", "operation": "tool_result",
              "tool_call_id": call_id}
    if hop.get("degraded"):
        # An OBSERVATION now, not an instruction: the model may weigh it and
        # ask again. The guarantee that used to ride here lives in the brief
        # HEAD, for the same reason GRAMMAR does.
        header["degraded"] = True
    emit({"header": header,
          "messages": [{"origin": "tool", "type": "tool_result", "id": call_id,
                        "text": rows if rows else "(no matching patterns)"}]})

# ---- Direction A: a tool_call goes out.
name = str(hop.get("tool_name") or "")
call_id = str(hop.get("tool_call_id") or "")
raw = ""
for m in msgs:
    if m.get("type") == "tool_call" and m.get("text"):
        raw = m["text"]
try:
    args = json.loads(raw or "{}")
    if not isinstance(args, dict):
        args = {}
except Exception:
    args = {}

query = str(args.get("query") or "").strip()
if not query:
    emit({"header": {"route": "lib_out", "operation": "tool_result",
                     "tool_call_id": call_id, "error_code": "query_missing"},
          "messages": [{"origin": "tool", "type": "tool_result", "id": call_id,
                        "text": "%s needs a non-empty `query` string" % name}]})

header = {"route": "lsearch_out", "lib_call_id": call_id}
if name == "catalogue_lookup":
    # The same corpus, filtered to the rows that describe a template. Those are
    # the rows whose first line opens with `CONTRACT --`, which is the sentence
    # that stops `requirement_missing` before the door has to.
    header["lib_kind"] = "template"
emit({"header": header,
      "messages": [{"origin": "user", "type": "text", "id": "", "text": query}]})
